<?phpnamespace app\api\controller\market;use app\api\controller\Controller;use hema\wechat\Pay as WxPay;use hema\alipay\Driver as AlipayPay;use think\facade\Cache;/** * 用户充值管理 */class Recharge extends Controller{	private $user;    /**     * 构造方法     */    public function initialize()    {        parent::initialize();        $this->user = $this->getUserDetail();   // 用户信息    }     /**     * 充值支付     * $pay_mode 1=微信 4=支付宝     * $browser 浏览器类型，只有H5才会传递     */    public function pay($money,$pay_mode,$recharge_plan_id = 0,$browser='')    {        $order_no = order_no();        $order = [            'order_no' => $order_no,            'pay_mode' => $pay_mode,//支付方式            'money' => $money,//充值金额            'user_id' => $this->user_id,            'remark' => '自助充值',            'recharge_plan_id' => $recharge_plan_id,//充值套餐        ];        Cache::set($order_no, $order,7200);//有效期2个小时                $mp = $this->mp;        //微信支付        if($pay_mode == 1){            $wx = new WxPay;            //网页其它浏览器平台支付接口            if($mp == 'h5' and $browser == 'other'){                if(!$result = $wx->h5($order_no,$money,'api/notify/recharge','用户充值')){                    return $this->renderError($wx->getError());                }            }            //微信小程序或微信浏览器支付接口            if($mp == 'weixin' or ($mp == 'h5' and $browser == 'weixin')){                if(!$result = $wx->jsapi($order_no,$money,$this->user['open_id'],'api/notify/recharge','用户充值')){                    return $this->renderError($wx->getError());                }            }        }        //支付宝支付        if($pay_mode == 4){            //非微信浏览器支付接口            if($mp == 'h5' and $browser != 'weixin'){                $alipay = new AlipayPay('aliweb');                if(!$result = $alipay->tradeWapPay($order_no,$money,'api/notify/recharge/mode/aliweb','h5/#/pages/index/index','用户充值')){                    $this->error = $alipay->getError();                    return false;                }            }            //支付宝小程序支付接口            if($mp == 'alipay'){                $alipay = new AlipayPay('aliapp');                if(!$result = $alipay->tradeCreate($order_no,$money,$this->user['alipay_open_id'],'api/notify/recharge/mode/aliapp','购买会员卡')){                    $this->error = $alipay->getError();                    return false;                }            }        }        return $this->renderSuccess([            'payment' => $result        ]);    }}